<?php
declare(strict_types=1);
require_once __DIR__.'/fixtures/PrintifyApiApprovalFixture.php';
use DigiForge\POD\PrintifyApiReadWorkflow;
use DigiForge\Connector\Printify\{ExternalOperationIntent,NativeReadConnector};
final class NativeReadGrantWordPressTest extends WP_UnitTestCase {
 private PrintifyApiApprovalFixture $fixture;
 protected function setUp():void{parent::setUp();$this->fixture=new PrintifyApiApprovalFixture();$this->fixture->boot();}
 protected function tearDown():void{$this->fixture->restore();parent::tearDown();}
 private function grant():array {$w=new PrintifyApiReadWorkflow();$p=PrintifyApiApprovalFixture::checked($w->prepare('personalized_pod',$this->fixture->integration,'SHOPS_READ',[]));$a=$this->fixture->approve($w,$p,'printify-api-read');$i=new ExternalOperationIntent(1,'personalized_pod',$this->fixture->integration,'SHOPS_READ',[],bin2hex(random_bytes(16)));return [$w,$p,$a,$i];}
 public function testGenuineFreshStepUpCannotReviveAnEarlierSessionGrant():void {
  self::assertTrue(method_exists($this->fixture,'refreshOwnerVerification'),'Long synthetic scenarios must renew through actual email verification.');
  [$w,$p,$a,$i]=$this->grant();self::assertNotWPError($w->bindNative($i,$p['hash'],$a['hash']));$old=wp_get_session_token();$manager=WP_Session_Tokens::get_instance(1);$state=$manager->get($old);$state['digiforge_email_verified_at']=time()-601;$manager->update($old,$state);self::assertFalse(DigiForge\PortalAccess\EmailAuthentication::recent(1));
  $this->fixture->refreshOwnerVerification();self::assertTrue(DigiForge\PortalAccess\EmailAuthentication::recent(1));self::assertNotSame(hash('sha256',$old),hash('sha256',wp_get_session_token()));$calls=0;$fake=static function()use(&$calls){++$calls;return PrintifyApiApprovalFixture::response([['id'=>12,'title'=>'Synthetic','sales_channel'=>'etsy']]);};add_filter('pre_http_request',$fake,100);
  try{self::assertWPError((new NativeReadConnector())->read($i));self::assertSame(0,$calls);[$next,$plan,$auth,$intent]=$this->grant();self::assertNotWPError($next->bindNative($intent,$plan['hash'],$auth['hash']));self::assertInstanceOf(DigiForge\Connector\Printify\ProviderResult::class,(new NativeReadConnector())->read($intent));self::assertSame(1,$calls);}finally{remove_filter('pre_http_request',$fake,100);}
 }
 public function testOwnerStepUpExpiryAtExecutionPreflightSendsNothingAndPreservesUnknown():void {
  [$w,$p,$a,$i]=$this->grant();self::assertNotWPError($w->bindNative($i,$p['hash'],$a['hash']));$expired=false;$calls=0;
  $query=static function(string $sql)use(&$expired):string{if(!$expired&&str_starts_with($sql,'SELECT context FROM')&&str_contains($sql,'native_printify_read_bound')){$expired=true;$manager=WP_Session_Tokens::get_instance(1);$token=wp_get_session_token();$s=$manager->get($token);$s['digiforge_email_verified_at']=time()-601;$manager->update($token,$s);}return $sql;};$fake=static function()use(&$calls){++$calls;return PrintifyApiApprovalFixture::response([]);};add_filter('query',$query);add_filter('pre_http_request',$fake,100);
  try{$r=(new NativeReadConnector())->read($i);self::assertWPError($r);self::assertTrue($expired);self::assertSame('UNKNOWN',$r->get_error_data()['outcome']);self::assertNull($r->get_error_data()['network_request_attempted']);self::assertFalse($r->get_error_data()['retry_permitted']);self::assertSame(0,$calls);}finally{remove_filter('query',$query);remove_filter('pre_http_request',$fake,100);}
 }
 public function testActualNativeGetRequiresBoundApprovedGrantAndIsOneUse():void {
  [$w,$p,$a,$i]=$this->grant();self::assertWPError((new NativeReadConnector())->read($i));self::assertNotWPError($w->bindNative($i,$p['hash'],$a['hash']));$calls=0;$fake=static function()use(&$calls){$calls++;return PrintifyApiApprovalFixture::response([['id'=>12,'title'=>'Synthetic bound shop','sales_channel'=>'etsy']]);};add_filter('pre_http_request',$fake,100);
  try{$r=(new NativeReadConnector())->read($i);self::assertInstanceOf(DigiForge\Connector\Printify\ProviderResult::class,$r);self::assertSame(200,$r->receipt['status']);self::assertSame($i->intentId,$r->receipt['intent_id']);self::assertFalse($r->jsonSerialize()['mutation_authorized']);self::assertWPError((new NativeReadConnector())->read($i));self::assertSame(1,$calls);}finally{remove_filter('pre_http_request',$fake,100);}
 }
 public function testBindingRejectsMismatchedIntentAndStopPreventsBindingOrDispatch():void {[$w,$p,$a,$i]=$this->grant();$wrong=new ExternalOperationIntent(1,'personalized_pod',$this->fixture->integration,'PROVIDERS_READ',[],bin2hex(random_bytes(16)));self::assertWPError($w->bindNative($wrong,$p['hash'],$a['hash']));self::assertNotWPError($w->bindNative($i,$p['hash'],$a['hash']));$this->fixture->setting('stop_all',true);self::assertWPError((new NativeReadConnector())->read($i));self::assertWPError($w->bindNative($i,$p['hash'],$a['hash']));}
 public function testCurrentSessionAndRevokedModuleCannotBorrowBoundGrant():void {[$w,$p,$a,$i]=$this->grant();self::assertNotWPError($w->bindNative($i,$p['hash'],$a['hash']));wp_get_current_user()->add_cap('manage_digiforge_connections',false);self::assertWPError((new NativeReadConnector())->read($i));wp_get_current_user()->add_cap('manage_digiforge_connections',true);WP_Session_Tokens::get_instance(1)->destroy(wp_get_session_token());self::assertWPError((new NativeReadConnector())->read($i));}
 public function testOneAuthorizationCannotBeReboundToAnotherNativeIntent():void {[$w,$p,$a,$i]=$this->grant();self::assertNotWPError($w->bindNative($i,$p['hash'],$a['hash']));$other=new ExternalOperationIntent(1,'personalized_pod',$this->fixture->integration,'SHOPS_READ',[],bin2hex(random_bytes(16)));self::assertWPError($w->bindNative($other,$p['hash'],$a['hash']));}
 public function testRejectedProviderResponsePreservesUncertainAttemptWithoutRetryingGrant():void {[$w,$p,$a,$i]=$this->grant();self::assertNotWPError($w->bindNative($i,$p['hash'],$a['hash']));$calls=0;$fake=static function()use(&$calls){$calls++;return PrintifyApiApprovalFixture::response(['invalid'=>'shape']);};add_filter('pre_http_request',$fake,100);try{$r=(new NativeReadConnector())->read($i);self::assertWPError($r);self::assertSame('UNKNOWN',$r->get_error_data()['outcome']??null);self::assertTrue($r->get_error_data()['network_request_attempted']);self::assertWPError((new NativeReadConnector())->read($i));self::assertSame(1,$calls);}finally{remove_filter('pre_http_request',$fake,100);}}
 public function testRenewedApprovalCannotReviveOldNativeAuthorization():void {[$w,$p,$a,$i]=$this->grant();self::assertNotWPError($w->bindNative($i,$p['hash'],$a['hash']));$key='printify-api-read:'.$p['hash'];$old=PrintifyApiApprovalFixture::checked(DigiForge\Security\ReviewedLocalEvidence::approved('policy','personalized_pod',$key));PortalAccessFixture::login($this->fixture->reviewer);$revoked=PrintifyApiApprovalFixture::checked(DigiForge\Security\ReviewedLocalEvidence::decide('policy','personalized_pod',$key,$old['revision'],$old['proposal_hash'],'REVOKED',wp_generate_uuid4()));$this->fixture->owner();$proposal=PrintifyApiApprovalFixture::checked(DigiForge\Security\ReviewedLocalEvidence::propose('policy','personalized_pod',$key,$old['payload'],time(),time()+900,wp_generate_uuid4(),$revoked['revision']));PortalAccessFixture::login($this->fixture->reviewer);PrintifyApiApprovalFixture::checked(DigiForge\Security\ReviewedLocalEvidence::decide('policy','personalized_pod',$key,$proposal['revision'],$proposal['proposal_hash'],'APPROVED',wp_generate_uuid4()));$this->fixture->owner();self::assertWPError($w->resolveNative($i));}
 public function testSessionRevocationDuringRetryStopsBeforeSecondPhysicalRequest():void {[$w,$p,$a,$i]=$this->grant();self::assertNotWPError($w->bindNative($i,$p['hash'],$a['hash']));$calls=0;$fake=static function()use(&$calls){$calls++;WP_Session_Tokens::get_instance(1)->destroy(wp_get_session_token());return PrintifyApiApprovalFixture::response([],500);};add_filter('pre_http_request',$fake,100);try{self::assertWPError((new NativeReadConnector())->read($i));self::assertSame(1,$calls);}finally{remove_filter('pre_http_request',$fake,100);}}
 public function testExpiredGrantDuringRetryCannotSendAgain():void {[$w,$p,$a,$i]=$this->grant();$load=new ReflectionMethod($w,'load');$load->setAccessible(true);$save=new ReflectionMethod($w,'save');$save->setAccessible(true);$auth=$load->invoke($w,'authorization',$a['hash']);$auth['expires_at']=time()+5;$short=$save->invoke($w,'authorization',$auth);self::assertNotWPError($w->bindNative($i,$p['hash'],$short['hash']));$calls=0;$fake=static function()use(&$calls){$calls++;if($calls===1)sleep(6);return PrintifyApiApprovalFixture::response([],500);};add_filter('pre_http_request',$fake,100);try{self::assertWPError((new NativeReadConnector())->read($i));self::assertSame(1,$calls);}finally{remove_filter('pre_http_request',$fake,100);}}
 public function testConcurrentNativeBindingCannotOverwriteAnotherWinner():void {[$w,$p,$a,$i]=$this->grant();global $wpdb;$key='digiforge_api_read_native_authorization_'.$a['hash'];$won=false;$race=static function(string $sql)use(&$won,$key,$wpdb):string{if(!$won&&str_starts_with($sql,'INSERT')&&str_contains($sql,$key)){$won=true;$wpdb->insert($wpdb->options,['option_name'=>$key,'option_value'=>str_repeat('f',64),'autoload'=>'no']);}return $sql;};add_filter('query',$race);try{self::assertWPError($w->bindNative($i,$p['hash'],$a['hash']));self::assertTrue($won);self::assertSame(str_repeat('f',64),$wpdb->get_var($wpdb->prepare('SELECT option_value FROM '.$wpdb->options.' WHERE option_name=%s',$key)));}finally{remove_filter('query',$race);}}
 public function testPostDispatchReceiptExceptionCannotClaimNoRequest():void {[$w,$p,$a,$i]=$this->grant();self::assertNotWPError($w->bindNative($i,$p['hash'],$a['hash']));$after=false;$fake=static function()use(&$after){$after=true;return PrintifyApiApprovalFixture::response([['id'=>12,'title'=>'Synthetic','sales_channel'=>'etsy']]);};$trip=static function(string $sql)use(&$after):string{if($after&&str_starts_with($sql,'SELECT context FROM'))throw new RuntimeException('Synthetic receipt outage');return $sql;};add_filter('pre_http_request',$fake,100);add_filter('query',$trip);try{$r=(new NativeReadConnector())->read($i);self::assertWPError($r);self::assertSame('UNKNOWN',$r->get_error_data()['outcome']);self::assertTrue($r->get_error_data()['network_request_attempted']);self::assertFalse($r->get_error_data()['retry_permitted']);}finally{remove_filter('pre_http_request',$fake,100);remove_filter('query',$trip);}}
 public function testBindingSqlFailureNeverProducesAcknowledgement():void {[$w,$p,$a,$i]=$this->grant();$trip=static function(string $sql):string{if(str_starts_with($sql,'INSERT IGNORE')&&str_contains($sql,'digiforge_api_read_native_authorization_'))throw new RuntimeException('Synthetic SQL outage');return $sql;};add_filter('query',$trip);try{self::assertWPError($w->bindNative($i,$p['hash'],$a['hash']));self::assertWPError($w->resolveNative($i));}finally{remove_filter('query',$trip);}}
}
